import React, { useMemo, useState } from 'react';
import {
  Activity, AlertTriangle, BarChart3, Bird, Bot, Boxes, BriefcaseBusiness, CheckCircle2, ClipboardCheck,
  ClipboardList, Coins, FileCheck2, FileText, HeartPulse, House, Landmark, MessageCircleMore, PackageCheck,
  Plus, ReceiptText, Scale, ShieldCheck, ShoppingCart, Stethoscope, TimerReset, Truck, UserCheck, Users, WalletCards
} from 'lucide-react';
import type { PlatformCoreStateV195, PlatformRoleV195, CurrencyV195 } from '../../modules/platform/PlatformCoreV19_5';
import type { EnterpriseCoreStateV196 } from '../../modules/enterprise/EnterpriseCoreV19_6';
import type { V20State } from '../../modules/v20/EnterprisePoultryCoreV20';
import { FlockAccountingWorkspaceV20 } from '../v20/FlockAccountingWorkspaceV20';
import {
  ManagedOperationsStateV197, createManagedContractV197, createFlockCycleV197, approvePrePlacementV197, receiveFlockV197,
  submitDailyFarmReportV197, generateVetDecisionAndTomorrowPlanV197, createFarmRequirementV197, decideFarmRequirementV197,
  financeApproveRequirementV197, issueFarmPurchaseOrderV197, confirmFarmPurchaseOrderSupplierV197, receiveFarmGoodsAndBookCostV197, addFarmCostEntryV197, createOperatingProtocolV197,
  sendFarmChatMessageV197, confirmChatExtractedDataV197, updateChatGroupModerationV197, markFarmChatReadV197, generateMarketingReadinessV197, createPoultrySaleV197,
  ownerDecideSaleV197, completeSaleDeliveryV197, generateCycleSettlementV197, financialFarmSummaryV197,
  executiveExceptionsV197, buildExecutiveBriefV197, calculateComplianceScoreV197, validateManagedOperationsV197
} from '../../modules/managed/ManagedPoultryOperationsV19_7';

interface Props {
  state: ManagedOperationsStateV197;
  platformCore: PlatformCoreStateV195;
  enterpriseCore: EnterpriseCoreStateV196;
  onChange: (next: ManagedOperationsStateV197) => void;
  v20: V20State;
  onV20Change: (next: V20State) => void;
  currentUserRole: PlatformRoleV195;
  currentUserName: string;
}

type Tab='overview'|'flockLedger'|'contracts'|'preplacement'|'daily'|'vet'|'approvals'|'finance'|'marketing'|'chat'|'timeline'|'exceptions';
const curLabel:Record<CurrencyV195,string>={SAR:'ر.س',YER_OLD:'ر.ي قديم',YER_NEW:'ر.ي جديد'};
const fmt=(n:number)=>new Intl.NumberFormat('ar-YE',{maximumFractionDigits:2}).format(n||0);
const pill=(status:string)=>status.includes('approved')||status.includes('active')||status.includes('ready')||status==='completed'||status==='matched'?'bg-emerald-500/15 text-emerald-300':status.includes('reject')||status.includes('critical')||status.includes('blocked')||status==='variance'?'bg-rose-500/15 text-rose-300':'bg-amber-500/15 text-amber-300';

export const ManagedOperationsWorkspaceV197:React.FC<Props>=({state,platformCore,enterpriseCore,onChange,v20,onV20Change,currentUserRole,currentUserName})=>{
  const [tab,setTab]=useState<Tab>('overview');
  const [farmId,setFarmId]=useState(state.farms[0]?.id||'');
  const selectedFarm=state.farms.find(f=>f.id===farmId)||state.farms[0];
  const selectedFlock=state.flock_cycles.find(f=>f.farm_id===selectedFarm?.id&&['active','marketing','selling','ready_for_placement','preparation'].includes(f.status));
  const executive=useMemo(()=>buildExecutiveBriefV197(state),[state]);
  const errors=useMemo(()=>validateManagedOperationsV197(state),[state]);
  const financeSummary=selectedFarm?financialFarmSummaryV197(state,selectedFarm.id,selectedFlock?.id):{cost_sar:0,revenue_sar:0,profit_loss_sar:0,outstanding_sar:0,paid_sar:0};
  const exceptions=executiveExceptionsV197(state);
  const user=platformCore.users.find(u=>u.id===platformCore.active_user_id);
  const canFinance=['system_owner','ceo','finance','sector_manager'].includes(currentUserRole);
  const canVet=['system_owner','ceo','vet_consultant','field_vet','sector_manager'].includes(currentUserRole);
  const canWorker=['system_owner','ceo','worker','supervisor','field_vet','vet_consultant'].includes(currentUserRole);
  const canOwner=['system_owner','ceo','farmer'].includes(currentUserRole);
  const canMarketing=['system_owner','ceo','marketing','sector_manager','finance'].includes(currentUserRole);

  const tabs:Array<[Tab,string,React.ReactNode,boolean]>=[
    ['overview','القيادة التشغيلية',<BarChart3/>,true],['flockLedger','سجل القطيع والتقارير',<Activity/>,true],['contracts','العقود والتعيين',<BriefcaseBusiness/>,['system_owner','ceo','sector_manager'].includes(currentUserRole)],
    ['preplacement','ما قبل الاستقبال',<ShieldCheck/>,canVet||canWorker],['daily','التشغيل اليومي',<ClipboardList/>,canWorker||canOwner],
    ['vet','الطبيب والذكاء',<Stethoscope/>,canVet],['approvals','الاحتياجات والموافقات',<FileCheck2/>,true],['finance','تكلفة المزرعة',<Coins/>,canFinance||canOwner],
    ['marketing','التسويق والبيع',<ShoppingCart/>,canMarketing||canOwner],['chat','مجموعات التشغيل',<MessageCircleMore/>,true],['timeline','السجل الزمني',<TimerReset/>,true],['exceptions','الاستثناءات',<AlertTriangle/>,['system_owner','ceo','sector_manager','vet_consultant','finance'].includes(currentUserRole)]
  ];

  return <div className="space-y-5" dir="rtl">
    <section className="rounded-[28px] border border-cyan-500/20 bg-gradient-to-l from-slate-950 via-cyan-950/20 to-emerald-950/20 p-5 shadow-2xl">
      <div className="flex flex-col xl:flex-row xl:items-center xl:justify-between gap-4">
        <div><div className="text-[11px] font-black text-cyan-300">V20.1 • MANAGED POULTRY OPERATIONS + FLOCK LEDGER</div><h2 className="text-2xl font-black text-white mt-1">إدارة القطيع التعاقدية من التجهيز حتى التسوية</h2><p className="text-xs text-slate-400 mt-2 max-w-4xl">العامل ينفذ ويسجل، الطبيب يعتمد القرار الطبي، المالية تعتمد المصروف، صاحب المزرعة يوافق على التكلفة حسب العقد، والذكاء الاصطناعي يجمع ويحلل وينبه دون إصدار قرار علاجي نهائي.</p></div>
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-2 min-w-[300px]">
          <Stat label="مزارع مُدارة" value={executive.active_managed_farms}/><Stat label="قطعان نشطة" value={executive.active_flocks}/><Stat label="طيور حالية" value={fmt(executive.active_birds)}/><Stat label="استثناءات" value={executive.open_exceptions} danger={executive.open_exceptions>0}/>
        </div>
      </div>
      <div className="mt-4 flex flex-col md:flex-row gap-2 md:items-center"><select className="spp-field max-w-lg" value={selectedFarm?.id||''} onChange={e=>setFarmId(e.target.value)}><option value="">اختر مزرعة مُدارة</option>{state.farms.map(f=><option key={f.id} value={f.id}>{f.name} — {f.governorate}/{f.district}</option>)}</select>{selectedFarm&&<div className="text-[11px] text-slate-400">التزام <b className="text-emerald-300">{calculateComplianceScoreV197(state,selectedFarm.id,selectedFlock?.id)}%</b> • {selectedFlock?`القطيع ${selectedFlock.flock_code} — يوم ${selectedFlock.age_days}`:'لا يوجد قطيع نشط'}</div>}</div>
    </section>

    <div className="flex gap-2 overflow-x-auto pb-1">{tabs.filter(x=>x[3]).map(([id,label,icon])=><button key={id} onClick={()=>setTab(id)} className={`shrink-0 rounded-xl px-3 py-2 text-xs font-black border flex items-center gap-2 ${tab===id?'bg-cyan-400 text-slate-950 border-cyan-300':'bg-slate-950 text-slate-300 border-slate-800'}`}>{React.cloneElement(icon as any,{className:'w-4 h-4'})}{label}</button>)}</div>

    {errors.length>0&&<div className="rounded-2xl border border-rose-500/30 bg-rose-500/5 p-3"><b className="text-rose-300 text-xs">تنبيه سلامة البيانات</b><div className="mt-2 text-[11px] text-rose-200/80 space-y-1">{errors.slice(0,6).map((e,i)=><div key={i}>• {e}</div>)}</div></div>}

    {tab==='overview'&&<Overview state={state} selectedFarm={selectedFarm} selectedFlock={selectedFlock} finance={financeSummary}/>} 
    {tab==='flockLedger'&&<FlockAccountingWorkspaceV20 v20={v20} managed={state} onChange={onV20Change} currentUserName={currentUserName} currentUserRole={currentUserRole}/>} 
    {tab==='contracts'&&<ContractsPanel state={state} platformCore={platformCore} onChange={onChange}/>} 
    {tab==='preplacement'&&<PrePlacementPanel state={state} selectedFlockId={selectedFlock?.id} onChange={onChange} currentUserName={currentUserName} canVet={canVet}/>} 
    {tab==='daily'&&<DailyPanel state={state} selectedFarmId={selectedFarm?.id} selectedFlockId={selectedFlock?.id} onChange={onChange} currentUserName={currentUserName} currentUserRole={currentUserRole}/>} 
    {tab==='vet'&&<VetPanel state={state} selectedFarmId={selectedFarm?.id} selectedFlockId={selectedFlock?.id} onChange={onChange} currentUserName={currentUserName}/>} 
    {tab==='approvals'&&<ApprovalsPanel state={state} core={platformCore} selectedFarmId={selectedFarm?.id} selectedFlockId={selectedFlock?.id} onChange={onChange} currentUserName={currentUserName} canFinance={canFinance} canOwner={canOwner}/>} 
    {tab==='finance'&&<FarmFinancePanel state={state} core={platformCore} selectedFarmId={selectedFarm?.id} selectedFlockId={selectedFlock?.id} onChange={onChange} currentUserName={currentUserName} canFinance={canFinance}/>} 
    {tab==='marketing'&&<MarketingPanel state={state} selectedFarmId={selectedFarm?.id} selectedFlockId={selectedFlock?.id} onChange={onChange} canOwner={canOwner}/>} 
    {tab==='chat'&&<ChatPanel state={state} selectedFarmId={selectedFarm?.id} onChange={onChange} currentUserId={user?.id||'current'} currentUserName={currentUserName} currentUserRole={currentUserRole}/>} 
    {tab==='timeline'&&<TimelinePanel state={state} selectedFarmId={selectedFarm?.id}/>} 
    {tab==='exceptions'&&<ExceptionsPanel state={state}/>} 
  </div>
}

const Stat=({label,value,danger=false}:{label:string;value:React.ReactNode;danger?:boolean})=><div className="rounded-2xl bg-slate-950/70 border border-slate-800 p-3 text-center"><div className="text-[9px] text-slate-500">{label}</div><b className={`text-lg ${danger?'text-rose-300':'text-cyan-300'}`}>{value}</b></div>;

const Overview=({state,selectedFarm,selectedFlock,finance}:{state:ManagedOperationsStateV197;selectedFarm:any;selectedFlock:any;finance:any})=>{
  const lastReport=state.daily_reports.find(r=>r.flock_id===selectedFlock?.id); const plan=state.daily_plans.find(p=>p.flock_id===selectedFlock?.id); const pendingReq=state.requirements.filter(r=>r.farm_id===selectedFarm?.id&&['pending'].includes(r.owner_decision)).length;
  return <div className="space-y-4">
    {!selectedFarm?<Empty text="لا توجد مزرعة مُدارة بعد. ابدأ من العقود والتعيين."/>:<>
      <div className="grid md:grid-cols-2 xl:grid-cols-4 gap-3"><Card icon={<Bird/>} title="القطيع الحالي" value={selectedFlock?fmt(selectedFlock.current_count):'—'} subtitle={selectedFlock?`${selectedFlock.flock_code} • يوم ${selectedFlock.age_days}`:'لا يوجد قطيع'}/><Card icon={<HeartPulse/>} title="النفوق التراكمي" value={selectedFlock?fmt(selectedFlock.cumulative_mortality):'—'} subtitle={lastReport?`اليوم ${lastReport.mortality}`:'لا يوجد تقرير'}/><Card icon={<Scale/>} title="الوزن / FCR" value={lastReport?.avg_weight_g?`${fmt(lastReport.avg_weight_g)} جم`:'—'} subtitle={lastReport?.estimated_fcr?`FCR ${lastReport.estimated_fcr}`:'بانتظار قياس موحد'}/><Card icon={<Coins/>} title="الربح/الخسارة SAR" value={fmt(finance.profit_loss_sar)} subtitle={`تكلفة ${fmt(finance.cost_sar)} • إيراد ${fmt(finance.revenue_sar)}`}/></div>
      <div className="grid xl:grid-cols-3 gap-4"><div className="xl:col-span-2 rounded-2xl border border-slate-800 bg-slate-950/70 p-4"><div className="flex items-center justify-between"><h3 className="font-black text-white">خطة العمل الحالية</h3><span className="text-[10px] text-slate-500">Daily Farm Plan</span></div>{plan?<div className="grid md:grid-cols-3 gap-3 mt-3 text-xs"><Mini label="العلف المستهدف" value={`${plan.target_feed_kg} كجم`}/><Mini label="الحرارة" value={`${plan.target_temperature_c}°C`}/><Mini label="عينات الوزن" value={`${plan.sampling_count} @ ${plan.sampling_time}`}/><div className="md:col-span-3 rounded-xl bg-slate-900 p-3 text-slate-300"><b className="text-white">المهام:</b> {[...plan.cleaning_tasks,...plan.maintenance_tasks,...plan.vaccination_tasks].join(' • ')||'لا توجد مهام استثنائية'}</div></div>:<div className="mt-4 text-xs text-slate-500">أغلق تقرير اليوم ثم اطلب من الطبيب/محرك القرار إنشاء خطة الغد.</div>}</div><div className="rounded-2xl border border-slate-800 bg-slate-950/70 p-4"><h3 className="font-black text-white">قرارات تنتظر</h3><div className="text-4xl font-black text-amber-300 mt-3">{pendingReq}</div><p className="text-[11px] text-slate-500 mt-2">طلبات تكلفة أو مشتريات تحتاج موافقة المالك/المالية.</p></div></div>
    </>}
  </div>
};

const ContractsPanel=({state,platformCore,onChange}:{state:ManagedOperationsStateV197;platformCore:PlatformCoreStateV195;onChange:(x:ManagedOperationsStateV197)=>void})=>{
  const vets=platformCore.staff.filter(s=>['vet_consultant','field_vet'].includes(s.role)&&s.availability!=='suspended'); const workers=platformCore.staff.filter(s=>['worker','supervisor'].includes(s.role)&&s.availability!=='suspended'); const finance=platformCore.users.filter(u=>u.role==='finance');
  const [form,setForm]=useState({name:'',phone:'',gov:'صنعاء',district:'',address:'',farm:'',house:'عنبر 1',length:80,width:12,capacity:15000,vet:vets[0]?.id||'',workers:workers[0]?.id?[workers[0].id]:[],finance:finance[0]?.id||'',start:new Date().toISOString().slice(0,10),end:new Date(Date.now()+180*86400000).toISOString().slice(0,10),currency:'SAR' as CurrencyV195,fee:0,commission:5,terms:'تسوية المصروفات حسب العقد وحتى بيع القطيع'});
  const create=()=>{if(!form.name||!form.phone||!form.farm||!form.vet||!form.workers.length||!form.finance)return alert('استكمل العميل والمزرعة والطبيب والعامل والمالية.');const v=vets.find(x=>x.id===form.vet)!,selectedWorkers=workers.filter(x=>form.workers.includes(x.id)),f=finance.find(x=>x.id===form.finance)!;onChange(createManagedContractV197(state,{customer:{full_name:form.name,phone:form.phone,governorate:form.gov,district:form.district,address:form.address,consent:{privacy:true,managed_data:true,marketing:false,accepted_at:new Date().toISOString()}},farm_name:form.farm,house:{name:form.house,length_m:Number(form.length),width_m:Number(form.width),capacity_birds:Number(form.capacity)},assigned_vet_id:v.id,assigned_vet_name:v.name,assigned_workers:selectedWorkers.map(w=>({id:w.id,name:w.name})),finance_officer_id:f.id,finance_officer_name:f.name,office_name:'مكتب المنصة المسؤول',start_date:form.start,end_date:form.end,currency:form.currency,management_fee:Number(form.fee),platform_commission_percent:Number(form.commission),payment_terms:form.terms}));setForm({...form,name:'',phone:'',farm:''});};
  const [flockFarm,setFlockFarm]=useState(state.farms[0]?.id||''); const farm=state.farms.find(x=>x.id===flockFarm); const house=state.houses.find(h=>h.farm_id===flockFarm); const [breed,setBreed]=useState('Ross 308'); const [hatchery,setHatchery]=useState(''); const addFlock=()=>{if(!farm||!house)return;onChange(createFlockCycleV197(state,{farm_id:farm.id,house_id:house.id,breed,hatchery_name:hatchery||'يحدد عند الحجز',target_market_weight_kg:2.2,target_placement_at:new Date(Date.now()+3*86400000).toISOString(),created_by:'الإدارة'}));};
  return <div className="grid xl:grid-cols-[430px_1fr] gap-4"><div className="rounded-2xl border border-slate-800 bg-slate-950/70 p-4 space-y-3"><h3 className="font-black text-white">عقد إدارة مزرعة جديد</h3><div className="grid grid-cols-2 gap-2"><input className="spp-field" placeholder="اسم العميل" value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/><input className="spp-field" placeholder="الهاتف" value={form.phone} onChange={e=>setForm({...form,phone:e.target.value})}/><input className="spp-field" placeholder="المحافظة" value={form.gov} onChange={e=>setForm({...form,gov:e.target.value})}/><input className="spp-field" placeholder="المديرية" value={form.district} onChange={e=>setForm({...form,district:e.target.value})}/></div><input className="spp-field" placeholder="العنوان" value={form.address} onChange={e=>setForm({...form,address:e.target.value})}/><input className="spp-field" placeholder="اسم المزرعة" value={form.farm} onChange={e=>setForm({...form,farm:e.target.value})}/><div className="grid grid-cols-3 gap-2"><input className="spp-field" placeholder="العنبر" value={form.house} onChange={e=>setForm({...form,house:e.target.value})}/><input className="spp-field" type="number" value={form.length} onChange={e=>setForm({...form,length:Number(e.target.value)})}/><input className="spp-field" type="number" value={form.width} onChange={e=>setForm({...form,width:Number(e.target.value)})}/></div><input className="spp-field" type="number" placeholder="الطاقة" value={form.capacity} onChange={e=>setForm({...form,capacity:Number(e.target.value)})}/><select className="spp-field" value={form.vet} onChange={e=>setForm({...form,vet:e.target.value})}>{vets.map(v=><option key={v.id} value={v.id}>الطبيب: {v.name}</option>)}</select><div className="rounded-xl border border-slate-800 bg-slate-900/60 p-3"><div className="text-[10px] text-slate-500 mb-2">العاملون الذين يختارهم الطبيب (واحد أو أكثر)</div><div className="grid grid-cols-2 gap-2">{workers.map(w=><label key={w.id} className="text-xs text-slate-300 flex items-center gap-2"><input type="checkbox" checked={form.workers.includes(w.id)} onChange={e=>setForm({...form,workers:e.target.checked?[...form.workers,w.id]:form.workers.filter(id=>id!==w.id)})}/>{w.name}</label>)}</div></div><select className="spp-field" value={form.finance} onChange={e=>setForm({...form,finance:e.target.value})}>{finance.map(v=><option key={v.id} value={v.id}>المالية: {v.name}</option>)}</select><button className="spp-button spp-button-primary w-full" onClick={create}><Plus className="w-4 h-4"/> إنشاء العقد والمزرعة وغرف التشغيل</button></div><div className="space-y-4"><div className="rounded-2xl border border-slate-800 bg-slate-950/70 p-4"><h3 className="font-black text-white">العقود النشطة</h3><div className="grid md:grid-cols-2 gap-3 mt-3">{state.managed_contracts.map(c=><div key={c.id} className="rounded-xl bg-slate-900 p-3"><div className="flex justify-between gap-2"><b className="text-white text-sm">{c.farm_name}</b><span className={`text-[10px] px-2 py-1 rounded-full ${pill(c.status)}`}>{c.status}</span></div><div className="text-[10px] text-slate-500 mt-2">{c.contract_number} • {c.customer_name}</div><div className="text-[11px] text-slate-400 mt-1">طبيب: {c.assigned_vet_name}</div><div className="text-[11px] text-slate-400">عمال: {c.assigned_worker_names.join('، ')}</div></div>)}</div></div><div className="rounded-2xl border border-slate-800 bg-slate-950/70 p-4 space-y-3"><h3 className="font-black text-white">إنشاء دورة قطيع</h3><select className="spp-field" value={flockFarm} onChange={e=>setFlockFarm(e.target.value)}><option value="">اختر المزرعة</option>{state.farms.map(f=><option key={f.id} value={f.id}>{f.name}</option>)}</select><div className="grid md:grid-cols-2 gap-2"><input className="spp-field" value={breed} onChange={e=>setBreed(e.target.value)} placeholder="السلالة"/><input className="spp-field" value={hatchery} onChange={e=>setHatchery(e.target.value)} placeholder="الفقاسة/المصدر"/></div><button className="spp-button spp-button-secondary" onClick={addFlock}><Bird className="w-4 h-4"/> إنشاء دورة وتجهيز Pre-Placement</button></div></div></div>
};

const PrePlacementPanel=({state,selectedFlockId,onChange,currentUserName,canVet}:{state:ManagedOperationsStateV197;selectedFlockId?:string;onChange:(x:ManagedOperationsStateV197)=>void;currentUserName:string;canVet:boolean})=>{
  const checklist=state.pre_placement.find(x=>x.flock_id===selectedFlockId); const flock=state.flock_cycles.find(f=>f.id===selectedFlockId); const [arrival,setArrival]=useState({hatchery:flock?.hatchery_name||'',breed:flock?.breed||'',docCount:15000,received:15000,mortality:0,plate:'',driver:'',phone:'',weight:'40,41,39,42'});
  if(!checklist)return <Empty text="اختر دورة في مرحلة التجهيز."/>;
  const patch=(p:any)=>onChange({...state,pre_placement:state.pre_placement.map(x=>x.id===checklist.id?{...x,...p}:x)});
  const receive=()=>{try{const weights=arrival.weight.split(',').map(v=>Number(v.trim())).filter(Boolean);onChange(receiveFlockV197(state,{flock_id:checklist.flock_id,received_at:new Date().toISOString(),hatchery_name:arrival.hatchery,breed:arrival.breed,document_count:Number(arrival.docCount),received_count:Number(arrival.received),arrival_mortality:Number(arrival.mortality),vehicle_plate:arrival.plate,driver_name:arrival.driver,driver_phone:arrival.phone,vehicle_disinfected:true,sample_weights_g:weights,photo_refs:['توثيق الاستلام'],documents:['مستند الشحن'],received_by:currentUserName}));}catch(e:any){alert(e.message)}};
  return <div className="grid xl:grid-cols-2 gap-4"><div className="rounded-2xl border border-slate-800 bg-slate-950/70 p-4 space-y-3"><div className="flex justify-between"><h3 className="font-black text-white">قائمة جاهزية العنبر</h3><span className={`text-[10px] px-2 py-1 rounded-full ${pill(checklist.status)}`}>{checklist.status}</span></div><div className="grid grid-cols-2 gap-2">{[['cleaning_completed','التنظيف'],['washing_completed','الغسيل'],['water_ready','الماء'],['feed_ready','العلف'],['electricity_ready','الكهرباء'],['generator_ready','المولد'],['equipment_ready','المعدات'],['litter_ready','الفرشة']].map(([k,l])=><label key={k} className="rounded-xl bg-slate-900 p-3 text-xs text-slate-300 flex gap-2 items-center"><input type="checkbox" checked={Boolean((checklist as any)[k])} onChange={e=>patch({[k]:e.target.checked})}/>{l}</label>)}</div><input className="spp-field" placeholder="المطهر المستخدم" value={checklist.disinfectant_name} onChange={e=>patch({disinfectant_name:e.target.value})}/><div className="grid grid-cols-3 gap-2"><input className="spp-field" placeholder="التركيز" value={checklist.disinfectant_concentration} onChange={e=>patch({disinfectant_concentration:e.target.value})}/><input className="spp-field" type="number" value={checklist.disinfectant_quantity} onChange={e=>patch({disinfectant_quantity:Number(e.target.value)})}/><input className="spp-field" type="number" value={checklist.preheat_target_c} onChange={e=>patch({preheat_target_c:Number(e.target.value)})}/></div><button className="spp-button spp-button-secondary" onClick={()=>patch({photo_refs:[...checklist.photo_refs,`صورة-${Date.now()}`]})}>إضافة إثبات صورة ({checklist.photo_refs.length})</button>{canVet&&<button className="spp-button spp-button-primary w-full" onClick={()=>onChange(approvePrePlacementV197(state,checklist.id,currentUserName))}><CheckCircle2 className="w-4 h-4"/> مراجعة واعتماد الطبيب</button>}</div><div className="rounded-2xl border border-slate-800 bg-slate-950/70 p-4 space-y-3"><h3 className="font-black text-white">استلام الصيصان</h3><div className="grid grid-cols-2 gap-2"><input className="spp-field" value={arrival.hatchery} onChange={e=>setArrival({...arrival,hatchery:e.target.value})} placeholder="الفقاسة"/><input className="spp-field" value={arrival.breed} onChange={e=>setArrival({...arrival,breed:e.target.value})} placeholder="السلالة"/><input className="spp-field" type="number" value={arrival.docCount} onChange={e=>setArrival({...arrival,docCount:Number(e.target.value)})} placeholder="حسب المستند"/><input className="spp-field" type="number" value={arrival.received} onChange={e=>setArrival({...arrival,received:Number(e.target.value)})} placeholder="المستلم"/><input className="spp-field" type="number" value={arrival.mortality} onChange={e=>setArrival({...arrival,mortality:Number(e.target.value)})} placeholder="نافق الوصول"/><input className="spp-field" value={arrival.plate} onChange={e=>setArrival({...arrival,plate:e.target.value})} placeholder="لوحة السيارة"/><input className="spp-field" value={arrival.driver} onChange={e=>setArrival({...arrival,driver:e.target.value})} placeholder="السائق"/><input className="spp-field" value={arrival.phone} onChange={e=>setArrival({...arrival,phone:e.target.value})} placeholder="هاتف السائق"/></div><input className="spp-field" value={arrival.weight} onChange={e=>setArrival({...arrival,weight:e.target.value})} placeholder="أوزان عينة جم مفصولة بفاصلة"/><button className="spp-button spp-button-primary w-full" onClick={receive} disabled={checklist.status!=='ready_for_placement'}><PackageCheck className="w-4 h-4"/> استلام واعتماد العدد الأولي</button><p className="text-[10px] text-slate-500">لن يسمح النظام بالاستلام قبل جاهزية العنبر واعتماد الطبيب.</p></div></div>
};

const DailyPanel=({state,selectedFarmId,selectedFlockId,onChange,currentUserName,currentUserRole}:{state:ManagedOperationsStateV197;selectedFarmId?:string;selectedFlockId?:string;onChange:(x:ManagedOperationsStateV197)=>void;currentUserName:string;currentUserRole:PlatformRoleV195})=>{
  const flock=state.flock_cycles.find(f=>f.id===selectedFlockId); const house=state.houses.find(h=>h.id===flock?.house_id); const last=state.daily_reports.find(r=>r.flock_id===selectedFlockId); const opening=last?.closing_birds||flock?.current_count||0;
  const protocol=state.protocols.find(p=>p.flock_id===selectedFlockId&&p.status==='active');
  const [f,setF]=useState({age:flock?.age_days||1,mortM:0,mortE:0,culls:0,feedOpen:last?.feed_closing_kg||0,feedIn:0,feedUsed:0,water:0,tmin:27,tmax:30,hmin:55,hmax:70,condition:'fasted' as 'fasted'|'fed'|'not_measured',time:protocol?.weighing_rule.time||'07:00',weights:'',expected:0,litter:'جيدة',equip:'',resp:false,dropp:false,notes:'',medicine:'',medicineIngredient:'',medicineQty:0,medicineUnit:'مل',vaccine:'',vaccineQty:0,vaccineUnit:'جرعة',vaccineBatch:'',coldChain:true,mediaCount:0});
  if(!selectedFarmId||!flock||!house)return <Empty text="اختر مزرعة وقطيع نشط."/>;
  const recommendedSamples=protocol?.weighing_rule.min_sample_count||Math.max(50,Math.min(200,Math.ceil(opening*.005)));
  const submit=(shift:'morning'|'evening'|'daily_close')=>{try{const weights=f.weights.split(',').map(v=>Number(v.trim())).filter(Boolean),mort=Number(f.mortM)+Number(f.mortE),feedClose=Number(f.feedOpen)+Number(f.feedIn)-Number(f.feedUsed);if(shift==='daily_close'&&f.condition!=='not_measured'&&weights.length<Math.min(recommendedSamples,10))throw new Error(`أدخل عينة وزن موثقة. البروتوكول يوصي بـ ${recommendedSamples} عينة؛ في النموذج الحالي أدخل 10 أوزان على الأقل ثم أكمل العينة الميدانية الموثقة.`);onChange(submitDailyFarmReportV197(state,{farm_id:selectedFarmId,farm_name:state.farms.find(x=>x.id===selectedFarmId)?.name||'',flock_id:flock.id,flock_code:flock.flock_code,house_id:house.id,report_date:new Date().toISOString().slice(0,10),age_days:Number(f.age),shift,entered_by:currentUserName,entered_by_role:currentUserRole,opening_birds:opening,mortality:mort,mortality_morning:Number(f.mortM),mortality_evening:Number(f.mortE),culls:Number(f.culls),feed_opening_kg:Number(f.feedOpen),feed_received_kg:Number(f.feedIn),feed_used_kg:Number(f.feedUsed),feed_closing_kg:feedClose,water_liters:Number(f.water),temperature_min_c:Number(f.tmin),temperature_max_c:Number(f.tmax),temperature_points_c:[Number(f.tmin),Number((Number(f.tmin)+Number(f.tmax))/2),Number(f.tmax)],humidity_min_pct:Number(f.hmin),humidity_max_pct:Number(f.hmax),weight_condition:f.condition,weight_time:f.time,sample_weights_g:weights,sampling_locations:['مقدمة العنبر','المنتصف','الخلف'],expected_weight_g:Number(f.expected)||undefined,daily_gain_g:undefined,medication_entries:f.medicine?[{name:f.medicine,active_ingredient:f.medicineIngredient||undefined,quantity:Number(f.medicineQty),unit:f.medicineUnit,vet_order_id:'يتطلب أمر الطبيب',photo_ref:f.mediaCount?`MED-PHOTO-${Date.now()}`:undefined}]:[],vaccination_entries:f.vaccine?[{name:f.vaccine,quantity:Number(f.vaccineQty),unit:f.vaccineUnit,batch:f.vaccineBatch||undefined,cold_chain_ok:f.coldChain,vet_order_id:'يتطلب أمر الطبيب'}]:[],litter_condition:f.litter,equipment_issues:f.equip?[f.equip]:[],respiratory_sound_observed:f.resp,abnormal_droppings_observed:f.dropp,media_refs:Array.from({length:f.mediaCount},(_,i)=>`FIELD-MEDIA-${Date.now()}-${i+1}`),notes:f.notes}));}catch(e:any){alert(e.message)}};
  return <div className="grid xl:grid-cols-[1.2fr_.8fr] gap-4"><div className="rounded-2xl border border-slate-800 bg-slate-950/70 p-4 space-y-3"><div className="flex justify-between gap-2"><div><h3 className="font-black text-white">إدخال بيانات العامل اليومية</h3><div className="text-[10px] text-slate-500">البيانات الإلزامية صباحًا/مساءً • العينة الموصى بها: {recommendedSamples} طائر • وقت الوزن: {protocol?.weighing_rule.time||f.time}</div></div><span className="rounded-xl bg-cyan-500/10 text-cyan-300 px-2 py-1 text-[10px] h-fit">اليوم {f.age}</span></div><div className="grid grid-cols-2 md:grid-cols-4 gap-2"><Field n="العمر يوم" v={f.age} set={v=>setF({...f,age:v})}/><Field n="نافق صباح" v={f.mortM} set={v=>setF({...f,mortM:v})}/><Field n="نافق مساء" v={f.mortE} set={v=>setF({...f,mortE:v})}/><Field n="استبعاد" v={f.culls} set={v=>setF({...f,culls:v})}/><Field n="علف أول اليوم كجم" v={f.feedOpen} set={v=>setF({...f,feedOpen:v})}/><Field n="علف وارد" v={f.feedIn} set={v=>setF({...f,feedIn:v})}/><Field n="علف مستهلك" v={f.feedUsed} set={v=>setF({...f,feedUsed:v})}/><Field n="ماء لتر" v={f.water} set={v=>setF({...f,water:v})}/><Field n="حرارة دنيا" v={f.tmin} set={v=>setF({...f,tmin:v})}/><Field n="حرارة عليا" v={f.tmax} set={v=>setF({...f,tmax:v})}/><Field n="رطوبة دنيا" v={f.hmin} set={v=>setF({...f,hmin:v})}/><Field n="رطوبة عليا" v={f.hmax} set={v=>setF({...f,hmax:v})}/></div><div className="grid md:grid-cols-3 gap-2"><select className="spp-field" value={f.condition} onChange={e=>setF({...f,condition:e.target.value as any})}><option value="fasted">وزن صائم</option><option value="fed">وزن معلف</option><option value="not_measured">لا يوجد وزن</option></select><input className="spp-field" type="time" value={f.time} onChange={e=>setF({...f,time:e.target.value})}/><input className="spp-field" type="number" placeholder="الوزن المتوقع جم" value={f.expected||''} onChange={e=>setF({...f,expected:Number(e.target.value)})}/></div><textarea className="spp-field" value={f.weights} onChange={e=>setF({...f,weights:e.target.value})} placeholder={`أوزان العينات بالجرام: 800,790,815... (البروتوكول ${recommendedSamples} عينة)`}/><div className="grid lg:grid-cols-2 gap-3"><div className="rounded-xl bg-slate-900/80 p-3 space-y-2"><b className="text-xs text-amber-300">العلاج المنفذ بأمر الطبيب</b><input className="spp-field" value={f.medicine} onChange={e=>setF({...f,medicine:e.target.value})} placeholder="اسم العلاج"/><input className="spp-field" value={f.medicineIngredient} onChange={e=>setF({...f,medicineIngredient:e.target.value})} placeholder="المادة الفعالة"/><div className="grid grid-cols-2 gap-2"><input className="spp-field" type="number" value={f.medicineQty} onChange={e=>setF({...f,medicineQty:Number(e.target.value)})} placeholder="الكمية"/><input className="spp-field" value={f.medicineUnit} onChange={e=>setF({...f,medicineUnit:e.target.value})}/></div></div><div className="rounded-xl bg-slate-900/80 p-3 space-y-2"><b className="text-xs text-sky-300">اللقاح المنفذ بأمر الطبيب</b><input className="spp-field" value={f.vaccine} onChange={e=>setF({...f,vaccine:e.target.value})} placeholder="اسم اللقاح"/><div className="grid grid-cols-2 gap-2"><input className="spp-field" type="number" value={f.vaccineQty} onChange={e=>setF({...f,vaccineQty:Number(e.target.value)})} placeholder="الكمية"/><input className="spp-field" value={f.vaccineBatch} onChange={e=>setF({...f,vaccineBatch:e.target.value})} placeholder="Batch/Lot"/></div><label className="text-[10px] text-slate-400 flex gap-2"><input type="checkbox" checked={f.coldChain} onChange={e=>setF({...f,coldChain:e.target.checked})}/> سلسلة التبريد سليمة</label></div></div><div className="grid md:grid-cols-2 gap-2"><input className="spp-field" value={f.litter} onChange={e=>setF({...f,litter:e.target.value})} placeholder="حالة الفرشة/تبن/نشارة"/><input className="spp-field" value={f.equip} onChange={e=>setF({...f,equip:e.target.value})} placeholder="مشكلة معدات إن وجدت"/></div><div className="flex flex-wrap gap-3 text-xs text-slate-300"><label><input type="checkbox" checked={f.resp} onChange={e=>setF({...f,resp:e.target.checked})}/> أصوات تنفسية/شخرة</label><label><input type="checkbox" checked={f.dropp} onChange={e=>setF({...f,dropp:e.target.checked})}/> فضلات/إسهال غير طبيعي</label><button className="spp-button spp-button-secondary !py-1.5" onClick={()=>setF({...f,mediaCount:f.mediaCount+1})}>إضافة صورة/فيديو ({f.mediaCount})</button></div><textarea className="spp-field" value={f.notes} onChange={e=>setF({...f,notes:e.target.value})} placeholder="ملاحظات، أصوات، سلوك، أي تغير في العلف أو الماء..."/><div className="grid grid-cols-3 gap-2"><button className="spp-button spp-button-secondary" onClick={()=>submit('morning')}>حفظ صباح</button><button className="spp-button spp-button-secondary" onClick={()=>submit('evening')}>حفظ مساء</button><button className="spp-button spp-button-primary" onClick={()=>submit('daily_close')}>إغلاق اليوم</button></div></div><div className="space-y-3"><div className="rounded-2xl border border-slate-800 bg-slate-950/70 p-4"><h3 className="font-black text-white">آخر التقارير</h3><div className="space-y-2 mt-3">{state.daily_reports.filter(r=>r.flock_id===flock.id).slice(0,8).map(r=><div key={r.id} className="rounded-xl bg-slate-900 p-3 text-xs"><div className="flex justify-between"><b className="text-cyan-300">{r.report_number}</b><span>{r.shift}</span></div><div className="grid grid-cols-2 gap-1 mt-2 text-slate-400"><span>نافق {r.mortality}</span><span>متبقي {r.closing_birds}</span><span>وزن {r.avg_weight_g||'—'} جم</span><span>FCR {r.estimated_fcr||'—'}</span><span>CV {r.cv_percent||'—'}%</span><span>علف متبقي {r.feed_closing_kg} كجم</span><span>علاج {r.medication_entries.length}</span><span>لقاحات {r.vaccination_entries.length}</span></div></div>)}</div></div><div className="rounded-2xl border border-slate-800 bg-slate-950/70 p-4"><b className="text-white text-sm">مهام الخطة التالية</b><div className="mt-2 space-y-2">{state.farm_tasks.filter(t=>t.flock_id===flock.id&&t.status==='pending').slice(0,8).map(t=><div key={t.id} className="rounded-xl bg-slate-900 p-2 text-[11px] text-slate-300"><b>{t.title}</b><div className="text-slate-500">{t.instructions} • {new Date(t.due_at).toLocaleString('ar-YE')}</div></div>)}</div></div></div></div>
};

const VetPanel=({state,selectedFarmId,selectedFlockId,onChange,currentUserName}:{state:ManagedOperationsStateV197;selectedFarmId?:string;selectedFlockId?:string;onChange:(x:ManagedOperationsStateV197)=>void;currentUserName:string})=>{
  const reports=state.daily_reports.filter(r=>r.flock_id===selectedFlockId); const last=reports[0]; const protocol=state.protocols.find(p=>p.flock_id===selectedFlockId&&p.status==='active'); const [minSample,setMinSample]=useState(80); const [feed,setFeed]=useState(90); const [temp,setTemp]=useState(32);
  if(!selectedFlockId)return <Empty text="اختر قطيعًا."/>;
  const createProt=()=>{onChange(createOperatingProtocolV197(state,{farm_id:selectedFarmId||'',flock_id:selectedFlockId,effective_from:new Date().toISOString().slice(0,10),created_by_vet:currentUserName,reason_for_version:protocol?'تحديث خطة التشغيل':'خطة البداية',feed_plan:[{age_from:1,age_to:7,feed_type:'بادئ',target_g_per_bird:Number(feed)},{age_from:8,age_to:21,feed_type:'نامي',target_g_per_bird:110},{age_from:22,age_to:45,feed_type:'ناهي',target_g_per_bird:150}],temperature_plan:[{age_from:1,age_to:7,target_c:Number(temp),tolerance_c:1},{age_from:8,age_to:21,target_c:29,tolerance_c:1.5},{age_from:22,age_to:45,target_c:25,tolerance_c:2}],humidity_target_pct:{min:55,max:70},weighing_rule:{frequency:'daily',time:'07:00',condition:'fasted',min_sample_count:Number(minSample)},vaccination_plan:[],biosecurity_rules:['تطهير الدخول','منع انتقال الأدوات بدون تطهير','توثيق المركبات والزوار']}));};
  return <div className="grid xl:grid-cols-[380px_1fr] gap-4"><div className="rounded-2xl border border-slate-800 bg-slate-950/70 p-4 space-y-3"><h3 className="font-black text-white">بروتوكول تشغيل القطيع</h3><div className="text-[11px] text-slate-500">الإصدار الحالي: V{protocol?.version||0}</div><Field n="أقل عدد عينات" v={minSample} set={setMinSample}/><Field n="علف بادئ جم/طير" v={feed} set={setFeed}/><Field n="حرارة البداية °C" v={temp} set={setTemp}/><button className="spp-button spp-button-primary w-full" onClick={createProt}><FileCheck2 className="w-4 h-4"/> إصدار بروتوكول جديد</button><p className="text-[10px] text-slate-500">أي تعديل ينشئ Version جديدًا ويحفظ القديم Superseded.</p></div><div className="space-y-3"><div className="rounded-2xl border border-slate-800 bg-slate-950/70 p-4"><div className="flex justify-between"><h3 className="font-black text-white">Veterinary Decision Support Engine</h3><Bot className="w-5 h-5 text-cyan-300"/></div>{last?<><div className="grid md:grid-cols-4 gap-2 mt-3"><Mini label="النفوق" value={last.mortality}/><Mini label="متوسط الوزن" value={`${last.avg_weight_g||'—'} جم`}/><Mini label="FCR" value={last.estimated_fcr||'—'}/><Mini label="الانحراف" value={`${last.weight_variance_percent||'—'}%`}/></div><button className="spp-button spp-button-primary mt-3" onClick={()=>onChange(generateVetDecisionAndTomorrowPlanV197(state,last.id,currentUserName))}><Stethoscope className="w-4 h-4"/> تحليل التقرير واعتماد خطة الغد</button></>:<div className="text-xs text-slate-500 mt-3">لا توجد تقارير يومية بعد.</div>}</div><div className="grid md:grid-cols-2 gap-3">{state.veterinary_decisions.filter(d=>d.flock_id===selectedFlockId).slice(0,6).map(d=><div key={d.id} className="rounded-2xl border border-slate-800 bg-slate-950/70 p-4"><div className="flex justify-between"><b className="text-white text-sm">{d.decision_number}</b><span className={`text-[10px] px-2 py-1 rounded-full ${d.ai_risk_level==='critical'?'bg-rose-500/15 text-rose-300':'bg-cyan-500/15 text-cyan-300'}`}>{d.ai_risk_level}</span></div><p className="text-xs text-slate-400 mt-2">{d.ai_summary}</p><div className="text-[11px] text-amber-300 mt-2">AI flags: {d.ai_flags.join(' • ')||'لا يوجد'}</div><div className="text-[10px] text-slate-500 mt-2">القرار الطبي: {d.vet_decision} {d.vet_name&&`• ${d.vet_name}`}</div></div>)}</div></div></div>
};

const ApprovalsPanel=({state,core,selectedFarmId,selectedFlockId,onChange,currentUserName,canFinance,canOwner}:{state:ManagedOperationsStateV197;core:PlatformCoreStateV195;selectedFarmId?:string;selectedFlockId?:string;onChange:(x:ManagedOperationsStateV197)=>void;currentUserName:string;canFinance:boolean;canOwner:boolean})=>{
  const [item,setItem]=useState('علف نامي'); const [reason,setReason]=useState('رصيد لا يكفي لليومين القادمين'); const [qty,setQty]=useState(1000); const [unit,setUnit]=useState('كجم'); const [cost,setCost]=useState(0); const [cat,setCat]=useState<any>('feed');
  const [supplier,setSupplier]=useState(''); const [unitPrice,setUnitPrice]=useState(0); const [transport,setTransport]=useState(0); const [fee,setFee]=useState(0); const [paymentMode,setPaymentMode]=useState<'cash'|'credit'|'transfer'>('cash');
  const [batch,setBatch]=useState(''); const [invoice,setInvoice]=useState('');
  if(!selectedFarmId||!selectedFlockId)return <Empty text="اختر مزرعة وقطيعًا."/>;
  const farmReqs=state.requirements.filter(r=>r.farm_id===selectedFarmId);
  const add=()=>onChange(createFarmRequirementV197(state,{farm_id:selectedFarmId,flock_id:selectedFlockId,requested_by:currentUserName,requested_by_role:'vet',category:cat,item_name:item,reason,quantity:Number(qty),unit,urgency:'normal',expected_need_at:new Date(Date.now()+24*3600000).toISOString(),estimated_cost:Number(cost)||undefined,currency:'SAR',owner_approval_required:true}));
  const issuePO=(r:any)=>{const offer=state.availability_offers.find(o=>o.product_name.toLowerCase().includes(r.item_name.toLowerCase())||r.item_name.toLowerCase().includes(o.product_name.toLowerCase())); const sp=supplier||offer?.company_name||'مورد معتمد'; const price=unitPrice||offer?.prices.find(p=>p.currency==='SAR')?.amount||r.estimated_cost/r.quantity||0; try{onChange(issueFarmPurchaseOrderV197(state,{requirement_id:r.id,supplier_company_id:offer?.company_id,supplier_name:sp,branch_id:offer?.branch_id,branch_name:offer?.branch_name,unit_price:Number(price),currency:'SAR',transport_cost:Number(transport),platform_fee:Number(fee),payment_mode:paymentMode,due_date:paymentMode==='credit'?new Date(Date.now()+7*86400000).toISOString().slice(0,10):undefined,issued_by_finance:currentUserName,source_offer_id:offer?.id,estimated_arrival_at:new Date(Date.now()+6*3600000).toISOString()}));}catch(e:any){alert(e.message)}};
  const receive=(po:any)=>{const req=state.requirements.find(r=>r.id===po.requirement_id); if(!req)return; try{onChange(receiveFarmGoodsAndBookCostV197(state,core,{farm_id:po.farm_id,flock_id:po.flock_id,requirement_id:req.id,po_number:po.po_number,supplier_name:po.supplier_name,branch_name:po.branch_name,item_name:po.item_name,ordered_quantity:po.quantity,received_quantity:po.quantity,unit:po.unit,received_at:new Date().toISOString(),received_by:currentUserName,batch_lot:batch||`LOT-${Date.now().toString().slice(-6)}`,cold_chain_required:req.category==='vaccine',temperature_c:req.category==='vaccine'?5:undefined,cold_chain_ok:req.category==='vaccine'?true:undefined,package_condition:'good',photo_refs:[],invoice_number:invoice||`INV-${Date.now().toString().slice(-7)}`}));}catch(e:any){alert(e.message)}};
  return <div className="space-y-4"><div className="grid xl:grid-cols-[390px_1fr] gap-4"><div className="rounded-2xl border border-slate-800 bg-slate-950/70 p-4 space-y-3"><h3 className="font-black text-white">احتياج جديد للمزرعة</h3><select className="spp-field" value={cat} onChange={e=>setCat(e.target.value)}><option value="feed">علف</option><option value="medicine">علاج</option><option value="vaccine">لقاح</option><option value="equipment">معدات</option><option value="disinfectant">مطهر</option><option value="litter">فرشة</option><option value="lab">مختبر</option><option value="transport">نقل</option></select><input className="spp-field" value={item} onChange={e=>setItem(e.target.value)}/><textarea className="spp-field" value={reason} onChange={e=>setReason(e.target.value)}/><div className="grid grid-cols-2 gap-2"><input className="spp-field" type="number" value={qty} onChange={e=>setQty(Number(e.target.value))}/><input className="spp-field" value={unit} onChange={e=>setUnit(e.target.value)}/></div><input className="spp-field" type="number" value={cost} onChange={e=>setCost(Number(e.target.value))} placeholder="تكلفة تقديرية SAR"/><button className="spp-button spp-button-primary w-full" onClick={add}><Plus className="w-4 h-4"/> إرسال للمالك والمالية</button><div className="rounded-xl bg-slate-900 p-3 text-[10px] text-slate-500">المسار: طلب الطبيب → موافقة المالك → اعتماد المالية → PO → تأكيد المورد → استلام → مطابقة → قيد تكلفة.</div></div><div className="space-y-3">{farmReqs.map(r=><div key={r.id} className="rounded-2xl border border-slate-800 bg-slate-950/70 p-4"><div className="flex flex-col md:flex-row md:items-center md:justify-between gap-2"><div><b className="text-white">{r.item_name}</b><div className="text-[10px] text-slate-500">{r.requirement_number} • {r.quantity} {r.unit} • {r.reason}</div></div><div className="flex gap-2 flex-wrap"><span className={`text-[10px] px-2 py-1 rounded-full ${pill(r.owner_decision)}`}>المالك: {r.owner_decision}</span><span className={`text-[10px] px-2 py-1 rounded-full ${pill(r.finance_status)}`}>المالية: {r.finance_status}</span><span className={`text-[10px] px-2 py-1 rounded-full ${pill(r.procurement_status)}`}>الشراء: {r.procurement_status}</span></div></div><div className="mt-3 flex flex-wrap gap-2">{canOwner&&r.owner_decision==='pending'&&<><button className="spp-button spp-button-primary" onClick={()=>onChange(decideFarmRequirementV197(state,r.id,'approved','موافق',currentUserName))}>موافقة المالك</button><button className="spp-button spp-button-secondary" onClick={()=>onChange(decideFarmRequirementV197(state,r.id,'clarification_requested','أحتاج توضيح',currentUserName))}>توضيح</button><button className="spp-button spp-button-danger" onClick={()=>onChange(decideFarmRequirementV197(state,r.id,'rejected','رفض المالك',currentUserName))}>رفض</button></>}{canFinance&&r.owner_decision==='approved'&&r.finance_status==='pending'&&<button className="spp-button spp-button-primary" onClick={()=>{try{onChange(financeApproveRequirementV197(state,r.id,true,currentUserName))}catch(e:any){alert(e.message)}}}>اعتماد المالية</button>}</div>{canFinance&&r.finance_status==='approved'&&r.procurement_status==='availability_check'&&<div className="mt-3 grid md:grid-cols-5 gap-2"><input className="spp-field" value={supplier} onChange={e=>setSupplier(e.target.value)} placeholder="المورد/يختار النظام"/><input className="spp-field" type="number" value={unitPrice} onChange={e=>setUnitPrice(Number(e.target.value))} placeholder="سعر الوحدة"/><input className="spp-field" type="number" value={transport} onChange={e=>setTransport(Number(e.target.value))} placeholder="النقل"/><input className="spp-field" type="number" value={fee} onChange={e=>setFee(Number(e.target.value))} placeholder="عمولة المنصة"/><button className="spp-button spp-button-secondary" onClick={()=>issuePO(r)}>إصدار PO</button></div>}</div>)}</div></div>
    <div className="rounded-2xl border border-slate-800 bg-slate-950/70 p-4"><div className="flex items-center justify-between"><h3 className="font-black text-white">أوامر الشراء والاستلام</h3><span className="text-[10px] text-slate-500">Three-Way Matching</span></div><div className="grid md:grid-cols-2 gap-3 mt-3">{state.purchase_orders.filter(po=>po.farm_id===selectedFarmId).map(po=><div key={po.id} className="rounded-xl border border-slate-800 bg-slate-900/70 p-3"><div className="flex justify-between gap-2"><div><b className="text-cyan-200">{po.po_number}</b><div className="text-[10px] text-slate-500">{po.item_name} • {po.supplier_name}{po.branch_name?` / ${po.branch_name}`:''}</div></div><span className={`text-[10px] px-2 py-1 rounded-full ${pill(po.status)}`}>{po.status}</span></div><div className="grid grid-cols-3 gap-2 mt-2"><Mini label="البضاعة" value={`${fmt(po.goods_amount)} ${po.currency}`}/><Mini label="النقل" value={fmt(po.transport_cost)}/><Mini label="الإجمالي" value={fmt(po.total_amount)}/></div><div className="mt-3 flex flex-wrap gap-2">{po.status==='issued'&&<button className="spp-button spp-button-secondary" onClick={()=>onChange(confirmFarmPurchaseOrderSupplierV197(state,po.id,{confirmed:true,estimated_arrival_at:new Date(Date.now()+6*3600000).toISOString(),actor:po.supplier_name}))}>تأكيد المورد</button>}{['supplier_confirmed','in_transit','issued'].includes(po.status)&&<><input className="spp-field max-w-[160px]" value={invoice} onChange={e=>setInvoice(e.target.value)} placeholder="رقم فاتورة المورد"/><input className="spp-field max-w-[140px]" value={batch} onChange={e=>setBatch(e.target.value)} placeholder="Batch/Lot"/><button className="spp-button spp-button-primary" onClick={()=>receive(po)}>تسجيل الاستلام</button></>}</div></div>)}</div>{state.purchase_orders.filter(po=>po.farm_id===selectedFarmId).length===0&&<div className="text-xs text-slate-500 mt-3">لا توجد أوامر شراء بعد.</div>}</div></div>
};

const FarmFinancePanel=({state,core,selectedFarmId,selectedFlockId,onChange,currentUserName,canFinance}:{state:ManagedOperationsStateV197;core:PlatformCoreStateV195;selectedFarmId?:string;selectedFlockId?:string;onChange:(x:ManagedOperationsStateV197)=>void;currentUserName:string;canFinance:boolean})=>{
  const sum=selectedFarmId?financialFarmSummaryV197(state,selectedFarmId,selectedFlockId):null; const [desc,setDesc]=useState('مصروف تشغيلي'); const [amount,setAmount]=useState(0); const [currency,setCurrency]=useState<CurrencyV195>('SAR'); const [category,setCategory]=useState<any>('feed');
  if(!selectedFarmId||!selectedFlockId)return <Empty text="اختر مزرعة وقطيعًا."/>;
  const add=()=>{if(!canFinance)return;onChange(addFarmCostEntryV197(state,core,{farm_id:selectedFarmId,flock_id:selectedFlockId,date:new Date().toISOString().slice(0,10),category,description:desc,amount:Number(amount),currency,debit_credit:'debit',party_name:'مورد/موظف',approved_by_finance:currentUserName,payment_status:'paid'}));};
  return <div className="space-y-4"><div className="grid md:grid-cols-4 gap-3"><Card icon={<Coins/>} title="إجمالي التكلفة SAR" value={fmt(sum?.cost_sar||0)} subtitle="Cost Center"/><Card icon={<ReceiptText/>} title="الإيرادات SAR" value={fmt(sum?.revenue_sar||0)} subtitle="مبيعات وتسويات"/><Card icon={<WalletCards/>} title="الآجل SAR" value={fmt(sum?.outstanding_sar||0)} subtitle="غير مسدد"/><Card icon={<Landmark/>} title="الربح/الخسارة" value={fmt(sum?.profit_loss_sar||0)} subtitle="حتى اللحظة"/></div><div className="grid xl:grid-cols-[360px_1fr] gap-4">{canFinance&&<div className="rounded-2xl border border-slate-800 bg-slate-950/70 p-4 space-y-3"><h3 className="font-black text-white">تحميل مصروف على القطيع</h3><select className="spp-field" value={category} onChange={e=>setCategory(e.target.value)}>{['chicks','feed','medicine','vaccine','labor','vet','transport','litter','equipment','electricity','fuel','lab','marketing','platform_fee','other'].map(x=><option key={x}>{x}</option>)}</select><input className="spp-field" value={desc} onChange={e=>setDesc(e.target.value)}/><input className="spp-field" type="number" value={amount} onChange={e=>setAmount(Number(e.target.value))}/><select className="spp-field" value={currency} onChange={e=>setCurrency(e.target.value as CurrencyV195)}><option value="SAR">SAR</option><option value="YER_OLD">YER قديم</option><option value="YER_NEW">YER جديد</option></select><button className="spp-button spp-button-primary w-full" onClick={add}>اعتماد القيد</button></div>}<div className="rounded-2xl border border-slate-800 overflow-hidden"><table className="w-full text-xs"><thead className="bg-slate-900 text-slate-400"><tr><th className="p-3 text-right">القيد</th><th>الفئة</th><th>الوصف</th><th>المبلغ</th><th>SAR</th><th>الحالة</th></tr></thead><tbody>{state.cost_entries.filter(e=>e.flock_id===selectedFlockId).map(e=><tr key={e.id} className="border-t border-slate-800"><td className="p-3 font-mono text-cyan-300">{e.entry_number}</td><td>{e.category}</td><td>{e.description}</td><td>{fmt(e.amount)} {curLabel[e.currency]}</td><td>{fmt(e.amount_sar)}</td><td>{e.payment_status}</td></tr>)}</tbody></table></div></div></div>
};

const MarketingPanel=({state,selectedFarmId,selectedFlockId,onChange,canOwner}:{state:ManagedOperationsStateV197;selectedFarmId?:string;selectedFlockId?:string;onChange:(x:ManagedOperationsStateV197)=>void;canOwner:boolean})=>{
  const flock=state.flock_cycles.find(f=>f.id===selectedFlockId); const report=state.daily_reports.find(r=>r.flock_id===selectedFlockId&&r.avg_weight_g); const [price,setPrice]=useState(2.2); const [buyer,setBuyer]=useState(''); const [birds,setBirds]=useState(0); const [office,setOffice]=useState('مكتب التسويق'); const [fees,setFees]=useState({office:0,platform:0,transport:0});
  if(!selectedFarmId||!flock)return <Empty text="اختر قطيعًا."/>;
  const readiness=()=>onChange(generateMarketingReadinessV197(state,flock.id,Number(price),'SAR',100)); const sale=()=>{const count=Number(birds)||flock.current_count,avg=(report?.avg_weight_g||0)/1000;onChange(createPoultrySaleV197(state,{farm_id:selectedFarmId,flock_id:flock.id,buyer_name:buyer||'مشتري قيد التأكيد',buyer_phone:'',marketing_office:office,marketing_contact:'مسؤول المكتب',governorate:state.farms.find(f=>f.id===selectedFarmId)?.governorate||'',district:'',address:'',birds_planned:count,avg_weight_kg:avg,price_per_kg:Number(price),currency:'SAR',office_fee:Number(fees.office),platform_fee:Number(fees.platform),transport_fee:Number(fees.transport)}));};
  return <div className="space-y-4"><div className="grid lg:grid-cols-2 gap-4"><div className="rounded-2xl border border-slate-800 bg-slate-950/70 p-4 space-y-3"><h3 className="font-black text-white">جاهزية التسويق</h3><input className="spp-field" type="number" step="0.01" value={price} onChange={e=>setPrice(Number(e.target.value))} placeholder="سعر السوق/كجم"/><button className="spp-button spp-button-secondary" onClick={readiness}>حساب Break-even وجاهزية البيع</button>{state.marketing_readiness.filter(x=>x.flock_id===flock.id).slice(0,1).map(x=><div key={x.id} className="rounded-xl bg-slate-900 p-3 text-xs text-slate-300"><div>وزن حالي: <b>{x.current_avg_weight_kg} كجم</b></div><div>سعر التعادل: <b className="text-amber-300">{fmt(x.break_even_price_per_kg)} SAR/kg</b></div><p className="text-[10px] text-slate-500 mt-2">{x.recommendation_summary}</p></div>)}</div><div className="rounded-2xl border border-slate-800 bg-slate-950/70 p-4 space-y-3"><h3 className="font-black text-white">عرض بيع</h3><input className="spp-field" value={buyer} onChange={e=>setBuyer(e.target.value)} placeholder="المشتري"/><div className="grid grid-cols-2 gap-2"><input className="spp-field" type="number" value={birds} onChange={e=>setBirds(Number(e.target.value))} placeholder={`العدد — المتاح ${flock.current_count}`}/><input className="spp-field" value={office} onChange={e=>setOffice(e.target.value)}/></div><div className="grid grid-cols-3 gap-2"><input className="spp-field" type="number" value={fees.office} onChange={e=>setFees({...fees,office:Number(e.target.value)})} placeholder="أجرة المكتب"/><input className="spp-field" type="number" value={fees.platform} onChange={e=>setFees({...fees,platform:Number(e.target.value)})} placeholder="أجرة المنصة"/><input className="spp-field" type="number" value={fees.transport} onChange={e=>setFees({...fees,transport:Number(e.target.value)})} placeholder="النقل"/></div><button className="spp-button spp-button-primary" onClick={sale}>إرسال العرض لصاحب المزرعة</button></div></div><div className="space-y-3">{state.poultry_sales.filter(s=>s.flock_id===flock.id).map(s=><div key={s.id} className="rounded-2xl border border-slate-800 bg-slate-950/70 p-4"><div className="flex flex-col md:flex-row md:justify-between gap-2"><div><b className="text-white">{s.sale_number} — {s.buyer_name}</b><div className="text-[10px] text-slate-500">{s.birds_planned} طائر • {s.avg_weight_kg} كجم • {s.price_per_kg} {s.currency}/كجم</div></div><span className={`text-[10px] px-2 py-1 rounded-full ${pill(s.status)}`}>{s.status}</span></div><div className="grid md:grid-cols-4 gap-2 mt-3"><Mini label="Gross" value={fmt(s.gross_expected)}/><Mini label="Net" value={fmt(s.net_expected)}/><Mini label="موافقة المالك" value={s.owner_decision}/><Mini label="المتبقي بالقطيع" value={flock.current_count}/></div><div className="mt-3 flex gap-2 flex-wrap">{canOwner&&s.owner_decision==='pending'&&<><button className="spp-button spp-button-primary" onClick={()=>onChange(ownerDecideSaleV197(state,s.id,'approved'))}>موافقة البيع</button><button className="spp-button spp-button-danger" onClick={()=>onChange(ownerDecideSaleV197(state,s.id,'rejected'))}>رفض</button></>}{s.owner_decision==='approved'&&s.status==='approved'&&<button className="spp-button spp-button-secondary" onClick={()=>{try{onChange(completeSaleDeliveryV197(state,s.id,{loaded_birds:s.birds_planned,loading_weight_kg:s.birds_planned*s.avg_weight_kg,vehicle_plate:'يستكمل',driver_name:'السائق',driver_phone:'',vehicle_disinfected:true,departed_at:new Date().toISOString(),delivered_birds:s.birds_planned,transport_mortality:0,arrived_at:new Date().toISOString(),pod_reference:`POD-${Date.now()}`,receiver_name:s.buyer_name}))}catch(e:any){alert(e.message)}}}>تسجيل التحميل والتسليم/POD</button>}</div></div>)}</div><button className="spp-button spp-button-primary" onClick={()=>{try{onChange(generateCycleSettlementV197(state,flock.id))}catch(e:any){alert(e.message)}}}>إنشاء تسوية وتقرير دورة</button></div>
};

const ChatPanel=({state,selectedFarmId,onChange,currentUserId,currentUserName,currentUserRole}:{state:ManagedOperationsStateV197;selectedFarmId?:string;onChange:(x:ManagedOperationsStateV197)=>void;currentUserId:string;currentUserName:string;currentUserRole:PlatformRoleV195})=>{
  const groups=state.chat_groups.filter(g=>!selectedFarmId||g.farm_id===selectedFarmId||!g.farm_id); const [groupId,setGroupId]=useState(groups[0]?.id||''); const [text,setText]=useState('اليوم النافق 18، الحرارة 29، الرطوبة 62، باقي من العلف 700'); const msgs=state.chat_messages.filter(m=>m.group_id===groupId).slice(0,30); const group=state.chat_groups.find(g=>g.id===groupId);
  const send=(voice=false)=>{if(!groupId||!text.trim())return;try{onChange(sendFarmChatMessageV197(state,{group_id:groupId,sender_id:currentUserId,sender_name:currentUserName,sender_role:currentUserRole,type:voice?'voice':'text',text,transcript:voice?text:undefined}));setText('');}catch(e:any){alert(e.message)}};
  const canModerate=Boolean(group&&(currentUserRole==='system_owner'||currentUserRole==='ceo'||group.owner_user_id===currentUserId||group.moderator_user_ids.includes(currentUserId)));
  return <div className="grid xl:grid-cols-[300px_1fr] gap-4"><div className="rounded-2xl border border-slate-800 bg-slate-950/70 p-3"><h3 className="font-black text-white p-2">المجموعات</h3><div className="space-y-2">{groups.map(g=><button key={g.id} onClick={()=>{setGroupId(g.id);onChange(markFarmChatReadV197(state,g.id,currentUserId))}} className={`w-full text-right rounded-xl p-3 border ${groupId===g.id?'bg-cyan-500/10 border-cyan-500/30':'bg-slate-900 border-slate-800'}`}><b className="text-xs text-white">{g.title}</b><div className="text-[9px] text-slate-500 mt-1">{g.category} • {g.posting_policy} • {g.status}</div></button>)}</div>{canModerate&&group&&<div className="mt-3 border-t border-slate-800 pt-3"><div className="text-[10px] text-slate-500 mb-2">إدارة المجموعة</div><div className="grid grid-cols-2 gap-2"><button className="spp-button spp-button-secondary !py-1.5" onClick={()=>onChange(updateChatGroupModerationV197(state,group.id,{actor_id:currentUserId,actor_role:currentUserRole,status:group.status==='muted'?'active':'muted'}))}>{group.status==='muted'?'إلغاء الكتم':'كتم المجموعة'}</button><button className="spp-button spp-button-secondary !py-1.5" onClick={()=>onChange(updateChatGroupModerationV197(state,group.id,{actor_id:currentUserId,actor_role:currentUserRole,posting_policy:group.posting_policy==='all'?'moderators_and_owner':'all'}))}>سياسة النشر</button></div></div>}</div><div className="rounded-2xl border border-slate-800 bg-slate-950/70 p-4 flex flex-col min-h-[500px]"><div className="flex-1 space-y-3 overflow-y-auto">{msgs.length===0?<div className="text-xs text-slate-500 text-center mt-20">لا توجد رسائل.</div>:msgs.map(m=><div key={m.id} className="rounded-2xl bg-slate-900 p-3 max-w-2xl"><div className="flex justify-between text-[9px] text-slate-500"><span>{m.sender_name} • {m.sender_role}</span><span>{new Date(m.sent_at).toLocaleString('ar-YE')} • {m.delivery_status||'sent'}</span></div><div className="text-sm text-slate-200 mt-2">{m.text}</div>{Object.keys(m.extracted_data).length>1&&<div className="mt-2 rounded-xl bg-cyan-500/5 border border-cyan-500/20 p-2 text-[11px] text-cyan-200">AI extracted: {Object.entries(m.extracted_data).filter(([k])=>k!=='raw_text').map(([k,v])=>`${k}=${String(v)}`).join(' • ')}</div>}{m.action_card&&m.type==='action_card'&&<div className="mt-2 rounded-xl border border-amber-500/20 bg-amber-500/5 p-2 text-[11px]"><b className="text-amber-300">{m.action_card.title}</b><div className="text-slate-500 mt-1">{m.action_card.status} • {m.action_card.actions.join(' / ')}</div></div>}{m.requires_confirmation&&<button className="mt-2 spp-button spp-button-primary" onClick={()=>onChange(confirmChatExtractedDataV197(state,m.id,currentUserName))}>تأكيد حفظ البيانات</button>}</div>)}</div><div className="mt-3 border-t border-slate-800 pt-3"><textarea className="spp-field" value={text} onChange={e=>setText(e.target.value)} placeholder="اكتب أو الصق تفريغ الملاحظة الصوتية..."/><div className="flex gap-2 mt-2"><button className="spp-button spp-button-primary" onClick={()=>send(false)}>إرسال</button><button className="spp-button spp-button-secondary" onClick={()=>send(true)}>محاكاة Voice-to-Data</button></div><div className="text-[9px] text-slate-600 mt-2">WhatsApp relay/Push/STT الحقيقي يحتاج مفاتيح مزود خارجي؛ سجل المحادثة الداخلي يعمل محليًا ويحافظ على الربط بالمزرعة.</div></div></div></div>
};

const TimelinePanel=({state,selectedFarmId}:{state:ManagedOperationsStateV197;selectedFarmId?:string})=><div className="rounded-2xl border border-slate-800 bg-slate-950/70 p-4"><h3 className="font-black text-white">Farm Command Timeline</h3><div className="mt-4 space-y-3">{state.timeline.filter(e=>!selectedFarmId||e.farm_id===selectedFarmId).slice(0,80).map(e=><div key={e.id} className="grid grid-cols-[120px_1fr] gap-3"><div className="text-[10px] text-slate-500">{new Date(e.at).toLocaleString('ar-YE')}</div><div className="border-r border-cyan-500/30 pr-3 pb-3"><b className="text-sm text-white">{e.action}</b><div className="text-[10px] text-slate-500">{e.actor} • {e.actor_role}{e.why&&` • ${e.why}`}</div>{e.cost!==undefined&&<div className="text-[10px] text-amber-300 mt-1">{fmt(e.cost)} {e.currency}</div>}</div></div>)}</div></div>;
const ExceptionsPanel=({state}:{state:ManagedOperationsStateV197})=><div className="grid md:grid-cols-2 gap-3">{executiveExceptionsV197(state).map(e=><div key={e.id} className={`rounded-2xl border p-4 ${e.severity==='critical'?'border-rose-500/30 bg-rose-500/5':'border-amber-500/30 bg-amber-500/5'}`}><div className="flex justify-between"><b className="text-white">{e.title}</b><span className="text-[10px] text-slate-400">{e.owner_role}</span></div><p className="text-xs text-slate-300 mt-2">{e.detail}</p><div className="text-[9px] text-slate-500 mt-2">{e.category} • {new Date(e.detected_at).toLocaleString('ar-YE')}</div></div>)}</div>;

const Card=({icon,title,value,subtitle}:{icon:React.ReactNode;title:string;value:React.ReactNode;subtitle:string})=><div className="rounded-2xl border border-slate-800 bg-slate-950/70 p-4"><div className="flex items-center justify-between text-xs text-slate-400"><span>{title}</span>{React.cloneElement(icon as any,{className:'w-5 h-5 text-cyan-300'})}</div><div className="text-2xl font-black text-white mt-3">{value}</div><div className="text-[10px] text-slate-500 mt-1">{subtitle}</div></div>;
const Mini=({label,value}:{label:string;value:React.ReactNode})=><div className="rounded-xl bg-slate-900 p-3"><div className="text-[9px] text-slate-500">{label}</div><b className="text-sm text-white">{value}</b></div>;
const Field=({n,v,set}:{n:string;v:number;set:(x:number)=>void})=><label className="text-[10px] text-slate-500">{n}<input className="spp-field mt-1" type="number" value={v} onChange={e=>set(Number(e.target.value))}/></label>;
const Empty=({text}:{text:string})=><div className="rounded-3xl border border-dashed border-slate-700 bg-slate-950/50 p-10 text-center text-sm text-slate-500">{text}</div>;
